import{_ as s,a0 as d,w as r,s as l,I as n,x as e,a1 as p,A as o,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"新蠕虫能感染 Linux 系统和嵌入式设备！ | LCTT x X-CMD","titleTemplate":false,"description":"新蠕虫能感染 Linux 系统和嵌入式设备！ | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"新蠕虫能感染 Linux 系统和嵌入式设备！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"新蠕虫能感染 Linux 系统和嵌入式设备！ | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/This new worm targets Linux PCs and embedded devices","title":"新蠕虫能感染 Linux 系统和嵌入式设备！","tag":"201312","desc":""},"relativePath":"201312/This new worm targets Linux PCs and embedded devices.md","filePath":"[post].md"}'),u={name:"201312/This new worm targets Linux PCs and embedded devices.md"};function m(x,t,P,T,C,L){const i=d("Link");return r(),l("div",null,[t[14]||(t[14]=n("h1",{id:"新蠕虫能感染-linux-系统和嵌入式设备",tabindex:"-1"},[e("新蠕虫能感染 Linux 系统和嵌入式设备！ "),n("a",{class:"header-anchor",href:"#新蠕虫能感染-linux-系统和嵌入式设备","aria-label":"Permalink to “新蠕虫能感染 Linux 系统和嵌入式设备！”"},"​")],-1)),t[15]||(t[15]=n("p",null,[n("strong",null,"来自赛门铁克研究员的消息，这个病毒通过2012年出现的 PHP 漏洞传播")],-1)),t[16]||(t[16]=n("p",null,"据美国国际数据集团（IDG）的新闻 —— 一个新的蠕虫病毒将目标指向那些运行了 Linux 和 PHP 的 x86 架构计算机，其变种还会对运行在其他芯片架构上的设备（诸如家用路由器和机顶盒）造成威胁。",-1)),t[17]||(t[17]=n("p",null,"根据赛门铁克研究员的介绍，这种病毒利用 php-cgi 上的一个漏洞进行传播，这个 php-cgi 组件的功能是允许 PHP 代码在通用网关接口（CGI）的配置环境下被执行。此漏洞的代号为 CVE-2012-1823（通过这个漏洞，攻击者可以远程执行任意代码，所以这种漏洞又叫“远程任意代码执行漏洞” —— 译者注）。2012年5月份，PHP 5.4.3 和 PHP 5.3.13 这两个版本已经打上补丁修复了这个漏洞。",-1)),n("p",null,[t[1]||(t[1]=e("这个赛门铁克的研究员在",-1)),p(i,{href:"http://www.symantec.com/connect/blogs/linux-worm-targeting-hidden-devices"},{default:o(()=>[...t[0]||(t[0]=[e("博客",-1)])]),_:1}),t[2]||(t[2]=e("中写道：这个名为“Linux.Darlloz”的新蠕虫病毒基于去年10月份放出的 PoC 代码（PoC：proof of concept，概念验证。利用目标计算机的漏洞，为对其进行攻击而设计的代码称为 exploit，而一个没有充分利用漏洞的 exploit，就是 PoC —— 译者注）。",-1))]),t[18]||(t[18]=a("<p>“在传播过程中，这段蠕虫代码会随机产生 IP 地址，通过特殊途径，利用普通的用户名密码发送 HTTP POST 请求，探测漏洞”，研究员解释道：“如果一个目标没有打上 CVE-2012-1823 的补丁，这台机器就会从病毒服务器下载蠕虫病毒，之后寻找下一个目标。”</p><p>这个唯一的蠕虫变种目前为止只感染了 x86 系统，这是因为这个病毒的二进制格式为 Intel 架构下的 ELF （Executable and Linkable Format）格式。</p><p>然而这个研究员警告说，黑客也为其他架构开发了病毒，包括 ARM，PPC，MIPS 和 MIPSEL。</p><p>这些计算机架构主要用于诸如家用路由器、网络监视器、机顶盒以及其他嵌入式设备。</p><p>“攻击者显然试图在最大范围内感染运行 Linux 的设备”，研究员又说：“然而我们还没有证实他们有没有攻击非 PC 设备。”</p><p>很多嵌入式设备的固件都使用 Linux 作为操作系统，并且使用 PHP 作为 Web 服务管理界面。这些设备比 PC 机 或服务器更容易被攻陷，因为它们不会经常更新软件。</p><p>在嵌入式设备为一个漏洞打上补丁，从来都不是件容易的事。很多厂商都不会定期公布更新信息，而当他们公布时，用户也不会被告知说这些更新解决了哪些安全问题。</p><p>并且，在嵌入式设备上更新软件比在计算机上需要更多的工作，以及更多的技术知识。用户需要知道哪些网站能提供这些更新，然后下载下来，通过 Web 界面更新到他们的设备中。</p><p>“很多用户也许压根就不知道他们家里或办公室的设备存在漏洞，”啰嗦的研究员说：“我们面临的另一个问题是，即使用户注意到他们用的是有漏洞的设备，这些设备的供应商却没有提供补丁，原因是技术落后，或者完全就是硬件的限制：内存不足，或 CPU 太慢，不足以支持这些软件的新版本。”</p><p>“为了保护他们的设备免受蠕虫感染，用户需要确认这些设备是否运行在最新的固件版本上，必要的话，升级固件，设置高强度的管理员密码，在防火墙那儿，或任何独立的设备那儿，屏蔽任何对 -/cgi-bin/php, -/cgi-bin/php5, -/cgi-bin/php-cgi, -/cgi-bin/php.cgi and -/cgi-bin/php4 的 HTTP POST 请求。”没完没了的赛门铁克研究员说道。</p><hr>",11)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),p(i,{href:"http://www.computerworld.com/s/article/9244409/This_new_worm_targets_Linux_PCs_and_embedded_devices?taxonomyId=122"},{default:o(()=>[...t[3]||(t[3]=[e("http://www.computerworld.com/s/article/9244409/This_new_worm_targets_Linux_PCs_and_embedded_devices?taxonomyId=122",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=e("译者：",-1)),p(i,{href:"https://github.com/bazz2"},{default:o(()=>[...t[5]||(t[5]=[e("bazz2",-1)])]),_:1}),t[8]||(t[8]=e(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=e("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原创翻译，",-1)),p(i,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[e("Linux中国",-1)])]),_:1}),t[13]||(t[13]=e(" 荣誉推出",-1))])])}const b=s(u,[["render",m]]);export{f as __pageData,b as default};
